create or replace function public.moreai_worker_claim_run(p_worker_id text,p_lease_seconds integer default 90)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.agent_runs%rowtype; seq bigint;
begin
 if p_worker_id is null or length(p_worker_id)<8 or length(p_worker_id)>128 or p_lease_seconds not between 15 and 900 then raise exception 'invalid worker claim'; end if;
 update public.agent_runs set status='failed',finished_at=now(),dead_lettered_at=now(),lease_owner=null,lease_expires_at=null,updated_at=now()
 where status='running' and lease_expires_at<now() and attempt>=max_attempts;
 insert into public.agent_run_events(run_id,event_type,sequence,payload)
 select id,'worker.dead_lettered',coalesce((select max(e.sequence) from public.agent_run_events e where e.run_id=agent_runs.id),0)+1,jsonb_build_object('reason','lease_expired_max_attempts')
 from public.agent_runs where dead_lettered_at is not null and finished_at > now()-interval '2 seconds' and status='failed';
 select * into r from public.agent_runs
 where ((status='queued' and available_at<=now()) or (status='running' and lease_expires_at<now()))
 and attempt<max_attempts and cancel_requested_at is null
 order by available_at,created_at for update skip locked limit 1;
 if not found then return null; end if;
 update public.agent_runs set status='running',attempt=attempt+1,lease_owner=p_worker_id,
 lease_expires_at=now()+make_interval(secs=>p_lease_seconds),heartbeat_at=now(),
 started_at=coalesce(started_at,now()),updated_at=now()
 where id=r.id returning * into r;
 select coalesce(max(sequence),0)+1 into seq from public.agent_run_events where run_id=r.id;
 insert into public.agent_run_events(run_id,event_type,sequence,payload) values(r.id,'worker.claimed',seq,jsonb_build_object('worker_id',p_worker_id,'attempt',r.attempt,'lease_seconds',p_lease_seconds));
 return jsonb_build_object('id',r.id,'user_id',r.user_id,'workspace_id',r.workspace_id,'conversation_id',r.conversation_id,'agent_definition_id',r.agent_definition_id,'status',r.status,'attempt',r.attempt,'max_attempts',r.max_attempts,'input',r.input,'lease_owner',r.lease_owner,'lease_expires_at',r.lease_expires_at);
end $$;

create or replace function public.moreai_worker_heartbeat(p_run_id uuid,p_worker_id text,p_lease_seconds integer default 90)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.agent_runs%rowtype;
begin
 if p_lease_seconds not between 15 and 900 then raise exception 'invalid lease duration'; end if;
 update public.agent_runs set heartbeat_at=now(),lease_expires_at=now()+make_interval(secs=>p_lease_seconds),updated_at=now()
 where id=p_run_id and status='running' and lease_owner=p_worker_id and cancel_requested_at is null
 returning * into r;
 if not found then return jsonb_build_object('alive',false,'cancel_requested',exists(select 1 from public.agent_runs where id=p_run_id and cancel_requested_at is not null)); end if;
 return jsonb_build_object('alive',true,'lease_expires_at',r.lease_expires_at);
end $$;

