create or replace function public.moreai_worker_finish_run(p_run_id uuid,p_worker_id text,p_status text,p_output jsonb default null,p_error jsonb default null,p_retry_delay_seconds integer default 30)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.agent_runs%rowtype; seq bigint; next_status text; dead boolean:=false;
begin
 if p_status not in('succeeded','failed','cancelled') then raise exception 'invalid terminal status'; end if;
 select * into r from public.agent_runs where id=p_run_id for update;
 if not found then raise exception 'run not found'; end if;
 if r.status in('succeeded','failed','cancelled') then return jsonb_build_object('run_id',r.id,'status',r.status); end if;
 if r.lease_owner is distinct from p_worker_id then raise exception 'worker lease mismatch'; end if;
 if r.cancel_requested_at is not null then next_status:='cancelled';
 elsif p_status='failed' and r.attempt<r.max_attempts then next_status:='queued';
 elsif p_status='failed' then next_status:='failed'; dead:=true;
 else next_status:=p_status; end if;
 if next_status='queued' then
  update public.agent_runs set status=next_status,error=p_error,available_at=now()+make_interval(secs=>greatest(1,least(p_retry_delay_seconds,3600))),lease_owner=null,lease_expires_at=null,heartbeat_at=null,updated_at=now() where id=r.id;
 else
  update public.agent_runs set status=next_status,output=p_output,error=p_error,finished_at=now(),dead_lettered_at=case when dead then now() else dead_lettered_at end,lease_owner=null,lease_expires_at=null,heartbeat_at=null,updated_at=now() where id=r.id;
 end if;
 select coalesce(max(sequence),0)+1 into seq from public.agent_run_events where run_id=r.id;
 insert into public.agent_run_events(run_id,event_type,sequence,payload) values(r.id,case when dead then 'worker.dead_lettered' else 'worker.'||next_status end,seq,jsonb_build_object('attempt',r.attempt,'error',p_error));
 return jsonb_build_object('run_id',r.id,'status',next_status,'attempt',r.attempt,'dead_lettered',dead);
end $$;

